import type { Neighborhood } from '../domain/types';

/**
 * Seuil de voisins vérifiés en dessous duquel un quartier reste jumelé avec un
 * quartier voisin, le temps d'avoir un fil vivant (§2 du cahier des charges).
 */
export const TWINNING_THRESHOLD = 50;

/**
 * Les lieux où Jiran existe : les 1541 communes d'Algérie, avec leur daïra et
 * leur wilaya — les 69 wilayas du découpage de 2026 (loi n° 26-06), dont les 11
 * dernières (codes 59 à 69) — et les 13 provinces et territoires du Canada.
 *
 * Deux pays, deux échelles. En Algérie on descend jusqu'à la commune, et la
 * position vérifie vraiment un quartier. Au Canada on s'arrête à la province :
 * le découpage n'y a pas d'équivalent utile de la commune, la position ne
 * vérifie donc que la province. L'écran le dit franchement plutôt que de
 * laisser croire à une vérification de quartier.
 *
 * Source pour l'Algérie : jeu de données public `geoalgeria`, repris tel quel
 * pour les noms bilingues, les daïras et les coordonnées ; c'est aussi la clé
 * commune avec As3ar (§7.2), d'où le code de wilaya officiel de chaque entrée.
 *
 * Le regroupement se fait par commune nommée, jamais par découpage géométrique
 * abstrait (§2) : les coordonnées ne servent qu'à vérifier qu'un nouveau voisin
 * habite bien là où il le déclare.
 *
 * Le rayon accepté n'est pas fixe : c'est la moitié de la distance à la commune
 * la plus proche, entre 2,5 et 20 km. Une commune serrée entre deux autres, en
 * ville, garde un rayon serré ; une commune du Sahara, seule à cent kilomètres
 * à la ronde, en obtient un large — sans quoi ses habitants ne pourraient
 * jamais confirmer leur position.
 */
